<template>
  <div class="service-app"><Sidebar/><main class="service-main">
    <header class="topbar"><label>⌕ <input v-model="search" placeholder="Araç, plaka, servis, hasar no, talep no..." /></label><span>{{ customerName }} · Filo Yöneticisi</span></header>
    <div class="content">
      <header class="page-title"><div><h1>⚒ Servis / Bakım & Hasar / Kaza</h1><p>Araç servis, bakım, hasar ve kaza süreçlerini tek ekrandan takip edin.</p></div><button class="primary" @click="openCreate('service')">＋ Yeni İş Emri</button></header>
      <section class="metrics">
        <article><i class="blue">⚒</i><small>Toplam Servis / Bakım</small><b>{{ serviceCount }}</b></article>
        <article><i class="red">⚠</i><small>Toplam Hasar / Kaza</small><b>{{ damageCount }}</b></article>
        <article><i class="blue">◷</i><small>Açık İş Emri</small><b>{{ openCount }}</b></article>
        <article class="due-metric" @click="statusFilter='due';activeTab='all'"><i class="blue">▣</i><small>Bakımı Yaklaşan Araçlar</small><b>{{ dueVehicles.length }}</b></article>
      </section>
      <div class="layout">
        <section class="main-col">
          <div class="filters"><label class="search">⌕ <input v-model="search" placeholder="Plaka, servis, iş emri no ara..." /></label><label><small>Araç Grubu</small><select v-model="groupFilter"><option value="all">Tümü</option><option v-for="g in groups" :key="g">{{g}}</option></select></label><label><small>İşlem Türü</small><select v-model="typeFilter"><option value="all">Tümü</option><option value="service">Servis / Bakım</option><option value="damage">Hasar / Kaza</option><option value="roadside">Yol Yardım</option><option value="expertise">Ekspertiz</option><option value="other">Diğer</option></select></label><label><small>Durum</small><select v-model="statusFilter"><option value="all">Tümü</option><option value="open">Açık</option><option>Beklemede</option><option>İşlemde</option><option>Servise Girdi</option><option>Eksper Bekliyor</option><option>Tamamlandı</option><option>İptal Edildi</option><option value="due">Bakımı yaklaşan</option></select></label><label><small>Başlangıç</small><input v-model="dateFrom" type="date"/></label><button class="filter-button" @click="page=1">⚲ Filtrele</button></div>
          <nav class="tabs"><button v-for="tab in tabs" :key="tab.key" :class="{active:activeTab===tab.key}" @click="activeTab=tab.key">{{tab.icon}} {{tab.name}} <b>{{tabCount(tab.key)}}</b></button></nav>
          <section class="panel"><header><b>▦ {{activeTab==='workorders'?'İş Emirleri':'Servis & Bakım Kayıtları'}}</b><button class="light-btn" @click="exportCsv">↓ Dışa Aktar</button></header><div class="table-wrap"><table><thead><tr><th>Tarih</th><th>Plaka</th><th>Araç / Model</th><th>İşlem Türü</th><th>Açıklama</th><th>Durum</th><th>Tutar (TL)</th><th>İş Emri No</th><th></th></tr></thead><tbody>
            <tr v-for="r in paginated" :key="r.id" :class="{selected:selected?.id===r.id}" @click="select(r)"><td>{{date(r.created_at)}}</td><td class="plate">{{r.vehicle_plate}}</td><td>{{r.vehicle_brand_model}}<small>{{vehicle(r.vehicle_id)?.year||'—'}} · {{fmt(vehicle(r.vehicle_id)?.mileage)}} km</small></td><td><span class="pill" :class="kind(r)">{{serviceType(r)}}</span></td><td class="desc">{{r.description}}<small v-if="r.details?.appointment_date">Randevu: {{date(r.details.appointment_date)}}</small></td><td><span class="state" :class="stateClass(r.status)">{{r.status}}</span></td><td>{{money(r.details?.invoice_amount||r.details?.total_estimated_cost||r.details?.labor_cost)}}</td><td>{{r.details?.work_order_no||'—'}}</td><td><button class="dots" @click.stop="openDetail(r)">•••</button></td></tr>
            <tr v-if="!paginated.length"><td colspan="9" class="empty"><b>Kayıt bulunamadı</b><small>Yeni iş emri oluşturarak süreci başlatabilirsiniz.</small><button @click="openCreate('service')">＋ Yeni İş Emri</button></td></tr>
          </tbody></table></div><footer>Toplam {{filtered.length}} kayıttan {{start}}–{{end}} görüntüleniyor <span><button :disabled="page<=1" @click="page--">‹</button> {{page}} / {{pages}} <button :disabled="page>=pages" @click="page++">›</button></span></footer></section>
        </section>
        <aside class="right-col">
          <section class="panel vehicle-panel"><header><b>⚙ Araç Bilgileri</b><select v-model="vehicleId"><option v-for="v in vehicles" :key="v.id" :value="v.id">{{v.plate}}</option></select></header><template v-if="currentVehicle"><div class="car">🚘 <span>● {{currentVehicle.is_active?'Aktif':'Pasif'}}</span></div><b>{{currentVehicle.brand}} {{currentVehicle.model}} {{currentVehicle.version||''}}</b><strong class="plate">{{currentVehicle.plate}}</strong><dl><dt>Marka / Model</dt><dd>{{currentVehicle.brand}} / {{currentVehicle.model}}</dd><dt>Şasi No</dt><dd>{{currentVehicle.chassis_no||'—'}}</dd><dt>Motor No</dt><dd>{{currentVehicle.engine_no||'—'}}</dd><dt>Renk</dt><dd>{{currentVehicle.color||'—'}}</dd><dt>Yıl</dt><dd>{{currentVehicle.year||'—'}}</dd><dt>Kira Başlangıç</dt><dd>{{date(currentVehicle.contract_start_date)}}</dd><dt>Kira Bitiş</dt><dd>{{date(currentVehicle.contract_end_date)}}</dd></dl><button class="wide" @click="router.push('/dashboard/vehicles/'+currentVehicle.id)">Araç Detaylarını Görüntüle</button></template><p v-else class="empty-note">Araç bulunamadı.</p></section>
          <section class="panel"><header><b>⚒ Bakımı Yaklaşan Araçlar</b><button class="link-btn" @click="statusFilter='due';activeTab='all'">Tümünü Gör</button></header><div class="due-list"><button v-for="v in dueVehicles.slice(0,5)" :key="v.id" @click="vehicleId=v.id">🚙 <span><b>{{v.plate}} · {{v.brand}} {{v.model}}</b><small>{{dueLabel(v)}}</small></span><i>Bakım</i></button><p v-if="!dueVehicles.length" class="empty-note">Bakım tarihi/kilometresi yaklaşan araç yok.</p></div></section>
          <section class="panel"><header><b>⚙ Hızlı İşlemler</b></header><div class="quick"><button @click="openCreate('service')">⚒ Yeni İş Emri</button><button @click="openCreate('appointment')">▣ Randevu Talep Et</button><button @click="showSuppliers=true">▦ Servis Firmaları</button><button @click="openCreate('damage')">⚠ Hasar Bildirimi</button></div></section>
        </aside>
      </div>
    </div>
  </main>
  <div v-if="modal" class="backdrop" @click.self="modal=''"><section class="dialog"><header><div><small>FLEETRENT · SERVİS YÖNETİMİ</small><h2>{{modal==='detail'?'İş Emri Detayı':createForm.service_type==='Hasar / Kaza'?'Hasar / Kaza Bildirimi':createForm.appointment?'Servis Randevusu':'Yeni İş Emri'}}</h2></div><button @click="modal=''">×</button></header>
    <form v-if="modal==='create'" @submit.prevent="createRequest"><div class="form-grid"><label>Araç<select v-model="createForm.vehicle_id" required><option value="" disabled>Araç seçin</option><option v-for="v in vehicles" :key="v.id" :value="v.id">{{v.plate}} · {{v.brand}} {{v.model}}</option></select></label><label>İşlem Türü<select v-model="createForm.service_type"><option>Periyodik Bakım</option><option>Mekanik Onarım</option><option>Genel Kontrol</option><option>Hasar / Kaza</option><option>Ekspertiz</option><option>Diğer</option></select></label><label>Tercih Edilen Tarih<input v-model="createForm.appointment_date" type="date"/></label><label>Güncel KM<input v-model.number="createForm.mileage" type="number" min="0"/></label><label>Servis Firması<select v-model="createForm.supplier_id"><option value="">Otomatik atama</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}} · {{s.city||'—'}}</option></select></label><label v-if="createForm.service_type==='Hasar / Kaza'">Olay Tarihi<input v-model="createForm.accident_date" type="date"/></label></div><label>Açıklama<textarea v-model.trim="createForm.description" required rows="3" placeholder="Servis / hasar detaylarını yazın"/></label><p v-if="error" class="error">{{error}}</p><footer><button type="button" class="cancel" @click="modal=''">Vazgeç</button><button class="primary" :disabled="saving">{{saving?'Kaydediliyor…':createForm.appointment?'Randevu Talep Et':'İş Emri Oluştur'}}</button></footer></form>
    <form v-else-if="modal==='detail'&&selected" @submit.prevent="saveDetail"><div class="record-summary"><b>{{selected.vehicle_plate}} · {{selected.vehicle_brand_model}}</b><span>{{selected.details?.work_order_no||'İş emri no yok'}} · {{date(selected.created_at)}}</span></div><div class="form-grid"><label>Durum<select v-model="detailForm.status"><option>Beklemede</option><option>Onaylandı</option><option>İşlemde</option><option>Servise Girdi</option><option>Eksper Bekliyor</option><option>Tamamlandı</option><option>İptal Edildi</option></select></label><label>Randevu Tarihi<input v-model="detailForm.appointment_date" type="date"/></label><label>İş Emri No<input v-model="detailForm.work_order_no"/></label><label>İşçilik (TL)<input v-model.number="detailForm.labor_cost" type="number" min="0"/></label><label>Parça (TL)<input v-model.number="detailForm.parts_cost" type="number" min="0"/></label><label>Tahmini Toplam (TL)<input v-model.number="detailForm.total_estimated_cost" type="number" min="0"/></label></div><label>Teşhis / Yapılan İşlem<textarea v-model="detailForm.diagnosis_notes" rows="3"/></label><label>Parça listesi (her satıra: ad | adet | birim fiyat)<textarea v-model="detailForm.parts_text" rows="2"/></label><details><summary>Fatura bilgisi</summary><div class="form-grid"><label>Fatura No<input v-model="detailForm.invoice_no"/></label><label>Fatura Tarihi<input v-model="detailForm.invoice_date" type="date"/></label><label>Fatura Tutarı<input v-model.number="detailForm.invoice_amount" type="number" min="0"/></label></div><label>Fatura Notu<textarea v-model="detailForm.invoice_notes" rows="2"/></label></details><p v-if="error" class="error">{{error}}</p><footer><button type="button" class="cancel" @click="modal=''">Kapat</button><button class="primary" :disabled="saving">{{saving?'Kaydediliyor…':'Kaydet'}}</button></footer></form>
  </section></div>
  <div v-if="showSuppliers" class="backdrop" @click.self="showSuppliers=false"><section class="dialog"><header><div><small>HİZMET NOKTALARI</small><h2>Servis Firmaları</h2></div><button @click="showSuppliers=false">×</button></header><article v-for="s in suppliers" :key="s.id" class="supplier"><div><b>{{s.name}}</b><small>{{s.contract_type||'Anlaşmalı servis'}} · {{s.district||''}} {{s.city||''}}</small><small>{{(s.services||[]).join(' · ')||'Servis hizmetleri'}} · {{s.phone||'Telefon yok'}}</small></div><button @click="showSuppliers=false;openCreate('service');createForm.supplier_id=String(s.id)">Seç</button></article><p v-if="!suppliers.length" class="empty-note">Servis firması tanımlanmamış.</p></section></div>
  </div>
</template>

<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Sidebar from '../components/Sidebar.vue'
const route=useRoute(),router=useRouter(),customerId=localStorage.getItem('fleetcar_customer_id'),customerName=localStorage.getItem('fleetcar_customer_name')||'Filo Yöneticisi'
const vehicles=ref([]),requests=ref([]),suppliers=ref([]),search=ref(''),groupFilter=ref('all'),typeFilter=ref('all'),statusFilter=ref('all'),dateFrom=ref(''),page=ref(1),pageSize=10,vehicleId=ref(''),selected=ref(null),modal=ref(''),showSuppliers=ref(false),saving=ref(false),error=ref('')
const createForm=reactive({vehicle_id:'',service_type:'Periyodik Bakım',appointment_date:'',mileage:null,supplier_id:'',accident_date:'',description:'',appointment:false})
const detailForm=reactive({status:'',appointment_date:'',work_order_no:'',diagnosis_notes:'',parts_text:'',labor_cost:null,parts_cost:null,total_estimated_cost:null,invoice_no:'',invoice_date:'',invoice_amount:null,invoice_notes:''})
const tabs=[{key:'all',name:'Tümü',icon:'◉'},{key:'service',name:'Servis / Bakım',icon:'⚒'},{key:'damage',name:'Hasar / Kaza',icon:'⚠'},{key:'roadside',name:'Yol Yardım',icon:'♧'},{key:'expertise',name:'Ekspertiz',icon:'◉'},{key:'other',name:'Diğer',icon:'▦'},{key:'workorders',name:'İş Emirleri',icon:'▤'}]
const activeTab=ref(route.name==='WorkOrders'?'workorders':route.query.tab||'all')
const groups=computed(()=>[...new Set(vehicles.value.map(v=>v.vehicle_segment||v.vehicle_type).filter(Boolean))].sort())
const customerRequests=computed(()=>requests.value.filter(r=>vehicles.value.some(v=>String(v.id)===String(r.vehicle_id))))
const serviceCount=computed(()=>customerRequests.value.filter(r=>r.type==='servis'&&!isDamage(r)).length),damageCount=computed(()=>customerRequests.value.filter(isDamage).length),openCount=computed(()=>customerRequests.value.filter(r=>!['Tamamlandı','İptal Edildi'].includes(r.status)).length)
const dueVehicles=computed(()=>vehicles.value.filter(v=>{const now=Date.now(),d=v.next_service_due_date?new Date(v.next_service_due_date):null,dateDue=d&&Number.isFinite(d.getTime())&&d.getTime()-now<30*86400000&&d.getTime()-now>-86400000,kmDue=v.next_service_due_km!=null&&Number(v.next_service_due_km)-Number(v.mileage||0)<=2000&&Number(v.next_service_due_km)>=Number(v.mileage||0);return dateDue||kmDue}))
const currentVehicle=computed(()=>vehicles.value.find(v=>String(v.id)===String(vehicleId.value))||vehicles.value[0]||null)
function vehicle(id){return vehicles.value.find(v=>String(v.id)===String(id))}
function isDamage(r){const s=String(r.details?.service_type||'').toLocaleLowerCase('tr-TR');return r.type==='servis'&&(s.includes('hasar')||s.includes('kaza')||r.status==='Kaza')}
function kind(r){if(r.type==='yol_yardim')return'roadside';if(r.type==='lastik'||r.type==='ikame_arac')return'other';const s=String(r.details?.service_type||'').toLocaleLowerCase('tr-TR');if(s.includes('ekspertiz'))return'expertise';if(isDamage(r))return'damage';return r.type==='servis'?'service':'other'}
function serviceType(r){if(r.type==='yol_yardim')return'Yol Yardım';if(r.type==='lastik')return'Lastik';if(r.type==='ikame_arac')return'İkame Araç';return r.details?.service_type||'Servis / Bakım'}
function tabCount(k){if(k==='all')return customerRequests.value.length;if(k==='workorders')return customerRequests.value.filter(r=>r.type==='servis').length;return customerRequests.value.filter(r=>kind(r)===k).length}
const filtered=computed(()=>customerRequests.value.filter(r=>{const v=vehicle(r.vehicle_id),q=search.value.toLocaleLowerCase('tr-TR').trim(),hay=[r.vehicle_plate,r.vehicle_brand_model,r.description,r.details?.work_order_no,r.details?.service_type,r.supplier_name].join(' ').toLocaleLowerCase('tr-TR'),k=kind(r),day=String(r.created_at||'').slice(0,10),group=v?.vehicle_segment||v?.vehicle_type;return(!q||hay.includes(q))&&(groupFilter.value==='all'||group===groupFilter.value)&&(typeFilter.value==='all'||k===typeFilter.value)&&(statusFilter.value==='all'||statusFilter.value==='open'&&!['Tamamlandı','İptal Edildi'].includes(r.status)||statusFilter.value==='due'&&dueVehicles.value.some(x=>String(x.id)===String(r.vehicle_id))||statusFilter.value===r.status)&&(!dateFrom.value||day>=dateFrom.value)&&(activeTab.value==='all'||activeTab.value==='workorders'?true:k===activeTab.value)}).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize))),paginated=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize)),start=computed(()=>filtered.value.length?(page.value-1)*pageSize+1:0),end=computed(()=>Math.min(page.value*pageSize,filtered.value.length))
watch(()=>route.name,n=>{if(n==='WorkOrders')activeTab.value='workorders';else if(activeTab.value==='workorders')activeTab.value='all'})
function fmt(n){return Number(n||0).toLocaleString('tr-TR')}function money(n){return n==null||n===''?'—':Number(n).toLocaleString('tr-TR')+' ₺'}
function date(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleDateString('tr-TR')}
function dueLabel(v){if(v.next_service_due_date)return'Bakım: '+date(v.next_service_due_date);if(v.next_service_due_km!=null)return fmt(Math.max(0,v.next_service_due_km-(v.mileage||0)))+' km içinde bakım';return'Bakım planlaması gerekli'}
function stateClass(s){return['Tamamlandı','Onaylandı'].includes(s)?'done':['İşlemde','Servise Girdi','Eksper Bekliyor'].includes(s)?'working':['Kaza','İptal Edildi'].includes(s)?'bad':'pending'}
async function load(){if(!customerId){vehicles.value=[];requests.value=[];return}const suffix='?customer_id='+encodeURIComponent(customerId);const [v,r,s]=await Promise.all([fetch('/api/vehicles'+suffix),fetch('/api/requests'+suffix),fetch('/api/suppliers?type=servis')]);if(v.ok)vehicles.value=await v.json();if(r.ok)requests.value=await r.json();if(s.ok)suppliers.value=await s.json();if(!vehicleId.value&&vehicles.value.length)vehicleId.value=vehicles.value[0].id}
function select(r){selected.value=r;vehicleId.value=r.vehicle_id}
function openCreate(type){Object.assign(createForm,{vehicle_id:currentVehicle.value?.id||vehicles.value[0]?.id||'',service_type:type==='damage'?'Hasar / Kaza':'Periyodik Bakım',appointment_date:'',mileage:currentVehicle.value?.mileage||null,supplier_id:'',accident_date:'',description:'',appointment:type==='appointment'});error.value='';modal.value='create'}
function openDetail(r){select(r);const d=r.details||{};Object.assign(detailForm,{status:r.status,appointment_date:d.appointment_date||'',work_order_no:d.work_order_no||'',diagnosis_notes:d.diagnosis_notes||'',parts_text:Array.isArray(d.parts_list)?d.parts_list.map(p=>[p.name||'',p.quantity||1,p.unit_price||''].join(' | ')).join('\n'):'',labor_cost:d.labor_cost??null,parts_cost:d.parts_cost??null,total_estimated_cost:d.total_estimated_cost??null,invoice_no:d.invoice_no||'',invoice_date:d.invoice_date||'',invoice_amount:d.invoice_amount??null,invoice_notes:d.invoice_notes||''});error.value='';modal.value='detail'}
async function createRequest(){saving.value=true;error.value='';const desc=createForm.description||createForm.service_type+' talebi',details={service_type:createForm.service_type,appointment_requested:Boolean(createForm.appointment),appointment_date:createForm.appointment_date||null,mileage:createForm.mileage,accident_date:createForm.accident_date||null};const r=await fetch('/api/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({vehicle_id:createForm.vehicle_id,supplier_id:createForm.supplier_id?Number(createForm.supplier_id):null,type:'servis',description:desc,details})}).catch(()=>null);saving.value=false;if(!r?.ok){error.value='İş emri oluşturulamadı. Araç kaydını kontrol edin.';return}const data=await r.json();modal.value='';await load();const entry=requests.value.find(x=>x.id===data.id);if(entry)openDetail(entry)}
async function saveDetail(){if(!selected.value)return;saving.value=true;error.value='';const r=selected.value,parts_list=detailForm.parts_text.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const [name,quantity,unit_price]=x.split('|').map(y=>y.trim());return{name,quantity:Number(quantity)||1,unit_price:Number(unit_price)||0}});const body={service_type:r.details?.service_type||serviceType(r),appointment_date:detailForm.appointment_date||null,work_order_no:detailForm.work_order_no||null,diagnosis_notes:detailForm.diagnosis_notes,parts_list,labor_cost:detailForm.labor_cost,parts_cost:detailForm.parts_cost,total_estimated_cost:detailForm.total_estimated_cost};const wo=await fetch('/api/requests/'+r.id+'/work-order',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).catch(()=>null);if(!wo?.ok){saving.value=false;error.value='İş emri alanları kaydedilemedi.';return}const st=await fetch('/api/requests/'+r.id+'/status',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:detailForm.status})}).catch(()=>null);if(!st?.ok){saving.value=false;error.value='Durum değişikliği kaydedilemedi.';return}if(detailForm.invoice_no&&detailForm.invoice_date&&detailForm.invoice_amount!=null){const inv=await fetch('/api/requests/'+r.id+'/invoice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({invoice_no:detailForm.invoice_no,invoice_date:detailForm.invoice_date,invoice_amount:detailForm.invoice_amount,invoice_notes:detailForm.invoice_notes})});if(!inv.ok){saving.value=false;error.value='Fatura kaydedilemedi.';return}}saving.value=false;modal.value='';await load()}
function exportCsv(){const heads=['Tarih','Plaka','Araç','İşlem','Açıklama','Durum','Tutar','İş Emri No'],rows=filtered.value.map(r=>[r.created_at,r.vehicle_plate,r.vehicle_brand_model,serviceType(r),r.description,r.status,r.details?.invoice_amount||r.details?.total_estimated_cost||'',r.details?.work_order_no||'']);const csv=[heads,...rows].map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(';')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download='fleetrent-servis-is-emirleri.csv';a.click();URL.revokeObjectURL(a.href)}
onMounted(load)
